def transforms(cells):
    res=[]; cur=list(cells)
    for _ in range(4):
        res.append(tuple(cur)); res.append(tuple((r,-c) for r,c in cur))
        cur=[(c,-r) for r,c in cur]
    out=[]
    for t in res:
        mr=min(r for r,c in t); mc=min(c for r,c in t)
        tt=tuple(sorted((r-mr,c-mc) for r,c in t))
        if tt not in out: out.append(tt)
    return out
def find_matches(grid, marker, target_vals):
    H,W=grid.shape
    res=[]
    for t in transforms(marker):
        h=max(r for r,c in t)+1; w=max(c for r,c in t)+1
        for r in range(H-h+1):
            for c in range(W-w+1):
                if all(grid[r+dr,c+dc]==target_vals for dr,dc in t):
                    res.append((t,r,c))
    return res
