def find_matches_ident(grid, marker, val):
    H,W=grid.shape
    h=max(r for r,c in marker)+1; w=max(c for r,c in marker)+1
    res=[]
    for r in range(H-h+1):
        for c in range(W-w+1):
            if all(grid[r+dr,c+dc]==val for dr,dc in marker):
                res.append((r,c))
